+	public function create_and_send($user, $email) {
+
+		$email = sanitize_email($email);
+
+		if ( ! $user instanceof \WP_User || ! is_email($email)) {
+			return [
+				'token'   => wp_generate_password(32, false, false),
+				'sent'    => false,
+				'generic' => true,
+			];
+		}
