+		if ($should_send) {
+			$this->send_email($user, $code);
+		}
+
+		return [
+			'token'   => $token,
+			'sent'    => $should_send,
+			'generic' => false,
+		];
+	}
+
+	/**
+	 * Verifies an OTP code and consumes it on success.
+	 *
