+			return $decoded;
+		}
+
+		return new \WP_Error(
+			'bigscoots-http-error',
+			sprintf(
+				/* translators: 1: HTTP status code, 2: API error message. */
+				__('BigScoots API error (%1$d): %2$s', 'ultimate-multisite'),
+				$status_code,
+				$this->get_api_error_message($body, wp_remote_retrieve_response_message($response))
+			),
+			['status' => $status_code]
+		);
+	}
