+	/**
+	 * Extracts a safe error message from an API response.
+	 *
+	 * @since 2.15.2
+	 *
+	 * @param string $body     Response body.
+	 * @param string $fallback HTTP response message.
+	 * @return string
+	 */
+	private function get_api_error_message(string $body, string $fallback): string {
+
